import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry triu_gemm_f32(
    .param .u64 __A,
    .param .u64 __B,
    .param .u64 __C,
    .param .u32 __N
)
{
    .reg .pred  %p_exit, %p_store0, %p_loop;
    .reg .u32   %rN, %ri, %rj, %rk, %r_iN, %r_idxC, %r_kN, %r_idxA, %r_idxB;
    .reg .u32   %r_cta_x, %r_cta_y, %r_ntid_x, %r_ntid_y, %r_tid_x, %r_tid_y;
    .reg .u64   %A, %B, %C, %addrA, %addrB, %addrC, %offA, %offB, %offC;
    .reg .f32   %sum, %va, %vb;
    // Load parameters
    ld.param.u64 %A, [__A];
    ld.param.u64 %B, [__B];
    ld.param.u64 %C, [__C];
    ld.param.u32 %rN, [__N];
    // Move special registers to GPRs
    mov.u32 %r_tid_x, %tid.x;
    mov.u32 %r_tid_y, %tid.y;
    mov.u32 %r_cta_x, %ctaid.x;
    mov.u32 %r_cta_y, %ctaid.y;
    mov.u32 %r_ntid_x, %ntid.x;
    mov.u32 %r_ntid_y, %ntid.y;
    // Compute thread coordinates
    mov.u32 %ri, %r_tid_y;
    mov.u32 %rj, %r_tid_x;
    mad.lo.u32 %ri, %r_cta_y, %r_ntid_y, %ri;
    mad.lo.u32 %rj, %r_cta_x, %r_ntid_x, %rj;
    // Bounds check
    setp.ge.u32 %p_exit, %ri, %rN;
    @%p_exit bra END;
    setp.ge.u32 %p_exit, %rj, %rN;
    @%p_exit bra END;
    // Compute C address for (i,j)
    mul.lo.u32 %r_iN, %ri, %rN;           // i * N
    add.u32 %r_idxC, %r_iN, %rj;          // i*N + j
    mul.wide.u32 %offC, %r_idxC, 4;       // * sizeof(float)
    add.u64 %addrC, %C, %offC;
    // If i > j, write 0 and exit (triu)
    setp.gt.u32 %p_store0, %ri, %rj;
    @!%p_store0 bra COMPUTE;
    mov.f32 %sum, 0f00000000;
    st.global.f32 [%addrC], %sum;
    bra END;
COMPUTE:
    // sum = 0; for k in [i, j]: sum += A[i,k] * B[k,j]
    mov.f32 %sum, 0f00000000;
    mov.u32 %rk, %ri;
LOOP:
    setp.gt.u32 %p_loop, %rk, %rj;
    @%p_loop bra LOOP_END;
    // A[i,k]
    add.u32 %r_idxA, %r_iN, %rk;          // i*N + k
    mul.wide.u32 %offA, %r_idxA, 4;
    add.u64 %addrA, %A, %offA;
    // B[k,j]
    mul.lo.u32 %r_kN, %rk, %rN;           // k * N
    add.u32 %r_idxB, %r_kN, %rj;          // k*N + j
    mul.wide.u32 %offB, %r_idxB, 4;
    add.u64 %addrB, %B, %offB;
    ld.global.f32 %va, [%addrA];
    ld.global.f32 %vb, [%addrB];
    fma.rn.f32 %sum, %va, %vb, %sum;
    add.u32 %rk, %rk, 1;
    bra LOOP;
LOOP_END:
    st.global.f32 [%addrC], %sum;
END:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("triu_gemm_f32")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        # Expect float32 square matrices on the same CUDA device.
        assert A.device.type == "cuda" and B.device.type == "cuda", "Inputs must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, "Only float32 is supported"
        assert A.dim() == 2 and B.dim() == 2 and A.shape == B.shape and A.shape[0] == A.shape[1], "Inputs must be square matrices"
        N = A.shape[0]
        C = torch.empty((N, N), device=A.device, dtype=A.dtype)

        module = _get_ptx_module()
        block_x, block_y, block_z = 32, 8, 1
        grid_x = (N + block_x - 1) // block_x
        grid_y = (N + block_y - 1) // block_y
        grid_z = 1

        module.launch(
            "triu_gemm_f32",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, block_z),
            arguments=[A, B, C, i32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

